MARK = "AccessibilityService"  # unused marker guard below uses the inserted sentence itself


def insert_long(lang, long_):
    L = T[lang]["L"]
    if L in long_:
        return long_
    if lang == "th":
        key = "เมนูการเลือกข้อความ"
        i = long_.index(key) + len(key)
        return long_[:i] + " " + L + long_[i:]
    parts = re.split(r"(?<=[.!?。।])(\s*)", long_)
    # parts: [s0, sp0, s1, sp1, ...] — Android 10 문장(두 번째) 뒤에 넣는다
    idx = 2  # s1 의 인덱스
    assert "10" in parts[idx], (lang, parts[idx][:60])
    sep = "" if lang in ("ja", "zh") else " "
    parts.insert(idx + 1, sep + L)
    return "".join(parts)


def main():
    assert len(T) == 21
    for f in sorted(glob.glob(os.path.join(ROOT, "i18n", "*.json"))):
        lang = os.path.basename(f)[:-5]
        if lang not in T:
            continue
        raw = open(f, encoding="utf-8").read()
        d = json.loads(raw)
        c = d["apps"]["clipboard"]
        c["long"] = insert_long(lang, c["long"])
        c["features"][0] = T[lang]["F"]
        c["faq"][0]["a"] = T[lang]["Q"]
        indent = 2 if raw.lstrip("{").lstrip("\r\n").startswith("  ") else None
        open(f, "w", encoding="utf-8", newline="\n").write(json.dumps(d, ensure_ascii=False, indent=indent) + "\n")
    for f in sorted(glob.glob(os.path.join(ROOT, "i18n", "guides", "*.json"))):
        lang = os.path.basename(f)[:-5]
        raw = open(f, encoding="utf-8").read()
        d = json.loads(raw)
        g = d["guides"]["android-clipboard-history"]
        g["sections"][1]["p"][2] = T[lang]["GP"]
        g["sections"][1]["steps"][1] = T[lang]["GS"]
        g["faq"][2]["a"] = T[lang]["GF"]
        g["updated"] = DATE
        indent = 2 if raw.lstrip("{").lstrip("\r\n").startswith("  ") else None
        open(f, "w", encoding="utf-8", newline="\n").write(json.dumps(d, ensure_ascii=False, indent=indent) + "\n")
    print("ok")


if __name__ == "__main__":
    main()
